import { createViteDevConfig } from "./createViteDevConfig.js";
import { sanitizeVueOutputPlugin } from "./sanitizeVueOutputPlugin.js";
import { mergeConfig } from "vite";
import dts from "vite-plugin-dts";
import { externalizeDeps } from "vite-plugin-externalize-deps";
import { libInjectCss } from "vite-plugin-lib-inject-css";
//#region src/configs/utils/createViteLibConfig.ts
const ModuleResolutionKind_NodeJs = 2;
const ModuleResolutionKind_Bundler = 100;
function createViteLibConfig(configEnv) {
	const useSources = process.env.USE_SOURCES === "1";
	const isServe = configEnv.command === "serve";
	return mergeConfig(createViteDevConfig(configEnv), {
		plugins: isServe ? [] : [
			libInjectCss(),
			dts({ compilerOptions: {
				declaration: true,
				declarationMap: true,
				moduleResolution: useSources ? ModuleResolutionKind_Bundler : ModuleResolutionKind_NodeJs,
				customConditions: useSources ? ["sources"] : []
			} }),
			externalizeDeps(),
			sanitizeVueOutputPlugin()
		],
		build: {
			cssCodeSplit: true,
			lib: {
				fileName: "lib",
				formats: ["es"],
				entry: ["src/index.ts"]
			},
			rolldownOptions: { output: {
				format: "es",
				preserveModules: true,
				preserveModulesRoot: "src",
				hoistTransitiveImports: false,
				inlineDynamicImports: false,
				entryFileNames: "[name].js",
				chunkFileNames: "[name]-[hash].js",
				assetFileNames: (chunkInfo) => {
					const moduleCss = chunkInfo.names.find((n) => n.endsWith(".module.css"));
					if (moduleCss) return moduleCss.replace(".module.css", ".css");
					return "[name][extname]";
				}
			} }
		}
	});
}
//#endregion
export { createViteLibConfig };
